Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

Ltac w4s_rng :=
  lazymatch goal with
  | |- ?lo <= bv_unsigned (ev ?E ?j) <= ?hi => let H := fresh "H" in kx_range (EVar j) H; exact H
  | |- 0 <= bv_unsigned (ev ?E ?j1) + 256 * bv_unsigned (ev ?E ?j2) < 65536 =>
      let H1 := fresh "H" in let H2 := fresh "H" in kx_range (EVar j1) H1; kx_range (EVar j2) H2; lia
  | |- 0 <= 256 * bv_unsigned (ev ?E ?j2) + bv_unsigned (ev ?E ?j1) < 65536 =>
      let H1 := fresh "H" in let H2 := fresh "H" in kx_range (EVar j1) H1; kx_range (EVar j2) H2; lia
  end.

Definition w4s_J1_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 x2 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x31 : word)
         (SS n SBL SBH : Z) (sbuf : list byte),
    mem_inv asegs mm ->
    bytes_at asegs mm SS sbuf -> Z.of_nat (length sbuf) = n ->
    unpoisoned mm SBL SBH -> SBL <= SS -> SS + n <= SBH ->
    rng RNG SS n -> rng RNG (shad SBL) (shlen (SBH - SBL + 7)) -> SBL mod 8 = 0 -> rng_aimg RNG ->
    0x60d000 <= SS -> SS + n <= 2^47 -> 10 <= n < 2^26 -> 0x60d000 <= SBL -> SBH <= 2^47 ->
    (forall (a0 a1 : word),
       evtF asegs RNG Q (MS (mkR x1 x2 gp tp x5 x6 x7 x8 x9 a0 a1 x12 x13 x14 x15 x16 (Z_to_bv 64 2147450880)
                                 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
                            F (Z_to_bv 64 0x90158) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 x2 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 (Z_to_bv 64 2147450880)
                             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
                        F (Z_to_bv 64 0x90144) fc None mm (seg_rom asegs)).

Theorem w4s_J1 : w4s_J1_case.
