    (forall (l1 l2 l3 LL : Z) (t0 a0 a1 a2 a7 : word),
       0 <= l1 < 65536 -> 0 <= l2 < 65536 -> 0 <= l3 < 65536 -> LL = l1 + l2 + l3 + 6 ->
