                                 (Z_to_bv 64 l3))
                            F (Z_to_bv 64 0x90224) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 x2 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 (Z_to_bv 64 DT) x15 x16 (Z_to_bv 64 2147450880)
                             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
